INSERT INTO __SCHEMA__.knowledge_entries VALUES ('KB-1', 'О барбершопе', 'Общее', 'Barberista, ул. Панфилова 98 (демо-адрес). Работаем каждый день 10:00–21:00. Парковка у входа на 4 машины. Оплата: Kaspi QR, карта, наличные. Без записи примем, если барбер свободен, но вечером лучше записаться.', '2026-10-30 17:27:27.021+00');
INSERT INTO __SCHEMA__.knowledge_entries VALUES ('KB-2', 'Правило предоплаты', 'Правила', 'Для услуг от 20 000 ₸ (VIP-ритуал) нужна предоплата 30% по ссылке. Запись подтверждается после предоплаты. Правило введено после отчёта по неявкам за октябрь: у VIP-ритуала было 25% неявок.', '2026-10-31 17:27:27.021+00');
INSERT INTO __SCHEMA__.knowledge_entries VALUES ('KB-3', 'Отмена и опоздание', 'Правила', 'Отменить или перенести визит можно бесплатно за 3 часа. Предоплата возвращается, если отмена больше чем за 24 часа. Если клиент опаздывает больше чем на 15 минут, барбер может сократить услугу или перенести её.', '2026-11-01 17:27:27.021+00');
INSERT INTO __SCHEMA__.knowledge_entries VALUES ('KB-4', 'Доплаты', 'Цены', 'Длинные волосы (ниже ушей) к мужской стрижке: +2 000 ₸. Борода длиннее 5 см: +1 000 ₸ к оформлению бороды. Камуфляж седины можно добавить к любой стрижке за 5 000 ₸.', '2026-11-02 17:27:27.021+00');
INSERT INTO __SCHEMA__.knowledge_entries VALUES ('KB-5', 'Акции', 'Цены', 'Каждая 6-я стрижка бесплатно (карта лояльности в CRM). Папа и сын: скидка 15% на детскую стрижку, если записаться вместе с мужской стрижкой. День рождения: скидка 10% на одну услугу в течение 7 дней, нужно показать удостоверение. Другие скидки обещать нельзя.', '2026-11-03 17:27:27.021+00');
INSERT INTO __SCHEMA__.knowledge_entries VALUES ('KB-6', 'Частые вопросы', 'FAQ', 'Детей стрижём с 4 лет. Работаем на косметике Reuzel и Layrite, горячее полотенце к каждому бритью. Кофе, чай и PlayStation бесплатно, пока вы ждёте. Фейд лучше освежать раз в 2–3 недели.', '2026-11-04 17:27:27.021+00');
