INSERT INTO __SCHEMA__.messages VALUES (1, 'CV-0001', 'client', 'Салем! хочу на вип-комплекс в эту пятницу, сколько стоит?', NULL, '2026-11-05 14:07:27.021+00');
INSERT INTO __SCHEMA__.messages VALUES (2, 'CV-0001', 'ai', 'Здравствуйте, Арман! VIP-ритуал: стрижка, борода, королевское бритьё и уход за лицом. Стоит 22 000 ₸, длится около 2,5 часов. На какое время в пятницу удобно?', NULL, '2026-11-05 14:08:27.021+00');
INSERT INTO __SCHEMA__.messages VALUES (3, 'CV-0001', 'client', 'после 6 вечера можно?', NULL, '2026-11-05 14:12:27.021+00');
INSERT INTO __SCHEMA__.messages VALUES (4, 'CV-0001', 'ai', 'В пятницу 06.11 к Тимуру Б. свободно 18:00 и 18:30. Какое время выбрать?', NULL, '2026-11-05 14:13:27.021+00');
INSERT INTO __SCHEMA__.messages VALUES (5, 'CV-0001', 'client', '18:00', NULL, '2026-11-05 14:17:27.021+00');
INSERT INTO __SCHEMA__.messages VALUES (6, 'CV-0001', 'system', 'AI booked VIP-ритуал with Тимур Б. on 2026-11-06 18:00 (AP-1001).', NULL, '2026-11-05 14:18:27.021+00');
INSERT INTO __SCHEMA__.messages VALUES (7, 'CV-0001', 'ai', 'Записали вас на пятницу в 18:00 к Тимуру Б. Для VIP-ритуала нужна предоплата 30%: 6 600 ₸, кнопка оплаты ниже.', NULL, '2026-11-05 14:18:27.021+00');
INSERT INTO __SCHEMA__.messages VALUES (8, 'CV-0001', 'pay', 'Payment for VIP-ритуал', 'PM-00001', '2026-11-05 14:18:27.021+00');
INSERT INTO __SCHEMA__.messages VALUES (9, 'CV-0001', 'system', 'Payment received: 6 600 ₸ (Kaspi QR). Booking confirmed.', NULL, '2026-11-05 14:25:27.021+00');
INSERT INTO __SCHEMA__.messages VALUES (10, 'CV-0001', 'ai', 'Оплата получена, спасибо! Ждём вас в пятницу в 18:00. Напомним за день до визита. Barberista: стиль без компромиссов 💈', NULL, '2026-11-05 14:26:27.021+00');
INSERT INTO __SCHEMA__.messages VALUES (11, 'CV-0002', 'client', 'вчера стригся у вас, фейд с одной стороны неровный. это нормально вообще??', NULL, '2026-11-05 16:27:27.021+00');
INSERT INTO __SCHEMA__.messages VALUES (12, 'CV-0002', 'ai', 'Очень жаль, что так вышло. Передаю ваш вопрос администратору: он свяжется с вами в течение 15 минут и предложит бесплатную коррекцию.', NULL, '2026-11-05 16:28:27.021+00');
INSERT INTO __SCHEMA__.messages VALUES (13, 'CV-0002', 'system', 'AI handed the chat to a human: complaint about quality.', NULL, '2026-11-05 16:28:27.021+00');
